export const money=n=>new Intl.NumberFormat('ko-KR').format(n);
export const sourceLink=id=>`https://stage.neordinary.xyz/products/goods-${id}`;
export function priceFor(p,quantity=0){const q=Number(quantity)||p.min;if(q<p.min)return null;const exact=p.tiers.find(([n])=>n===q);const tier=exact||p.tiers.filter(([n])=>n<=q).at(-1);return tier?{quantity:q,basis:tier[0],price:tier[1],exact:!!exact}:null;}
export function filterProducts(list,f={}){const query=String(f.query||'').toLowerCase().trim().replace(/수건|타올/g,'타월');let results=list.filter(p=>{const v=priceFor(p,f.quantity);const text=`${p.name} ${p.category} ${p.brand} ${p.detail} ${p.id}`.toLowerCase();return(!query||query.split(/\s+/).every(t=>text.includes(t)))&&(!f.category||f.category==='전체'||p.category===f.category)&&(!f.purpose||p.purposes.includes(f.purpose))&&v&&(!f.budget||v.price<=Number(f.budget))&&(!f.printOnly||p.print)&&(!f.savedOnly||f.saved?.includes(p.id));});if(f.sort==='price-asc')results.sort((a,b)=>priceFor(a,f.quantity).price-priceFor(b,f.quantity).price);if(f.sort==='price-desc')results.sort((a,b)=>priceFor(b,f.quantity).price-priceFor(a,f.quantity).price);if(f.sort==='production')results.sort((a,b)=>a.days[1]-b.days[1]);return results;}
export function validateEventDate(value,today=new Date()){if(!value)return true;const d=new Date(`${value}T00:00:00`);return Number.isFinite(d.getTime())&&d>=new Date(today.getFullYear(),today.getMonth(),today.getDate());}
